static const char editor_scene_source[] =
    "/*\n"
    " * Generated by Rohr Engine.\n"
    " * This generated file is not covered by Rohr Engine's LGPL-3.0-only license.\n"
    " * The project's developer may use, modify, and distribute it without restriction.\n"
    " */\n"
    "\n"
    "#include \"scene/project.h\"\n"
    "#include <stdio.h>\n"
    "\n"
    "/* Disposable simulation entry point. Regeneration replaces this file.\n"
    " * The runner owns engine/graphics startup, updates, and shutdown. */\n"
    "typedef struct Scene {\n"
    "    Entity objects;\n"
    "    InputControllerId controllers[ROHR_INPUT_CONTROLLER_LIMIT];\n"
    "    ViewportId viewports[MAX_VIEWPORTS];\n"
    "} Scene;\n"
    "\n"
    "static EngineResult scene_initialize(void *context) {\n"
    "    Scene *scene = context;\n"
    "    EngineResult result = project_settings_apply();\n"
    "    if(rohr_error_check(result)) return result;\n"
    "    if(project._project.controller_count > ROHR_INPUT_CONTROLLER_LIMIT)\n"
    "        return rohr_error_result_error(ERROR_MEMORY_POOL_FULL);\n"
    "    for(size_t i = 0; i < project._project.controller_count; ++i) {\n"
    "        InputControllerIdResult controller = rohr_controller_create(project._project.controllers[i]);\n"
    "        if(rohr_error_check(controller)) return rohr_error_result_error(controller.result.error);\n"
    "        scene->controllers[i] = controller.result.value;\n"
    "    }\n"
    "    EntityResult created = rohr_object_create(project);\n"
    "    if(rohr_error_check(created)) return rohr_error_result_error(created.result.error);\n"
    "    scene->objects = created.result.value;\n"
    "    if(project.viewport_count > MAX_VIEWPORTS) return rohr_error_result_error(ERROR_MEMORY_POOL_FULL);\n"
    "    for(size_t i = 0; i < project.viewport_count; ++i) {\n"
    "        ViewportCreateDescription recipe = *project.viewports[i];\n"
    "        ViewportCreateItemDescription items[MAX_VIEWPORT_ITEMS];\n"
    "        bool camera_binding_needed = false;\n"
    "        if(recipe.item_count > MAX_VIEWPORT_ITEMS) return rohr_error_result_error(ERROR_MEMORY_POOL_FULL);\n"
    "        for(size_t j = 0; j < recipe.item_count; ++j) {\n"
    "            items[j] = recipe.items[j];\n"
    "            // Bind the created root; authored identities resolve every descendant locally.\n"
    "            if(items[j].camera_object) {\n"
    "                items[j].camera_object = &project._project.root;\n"
    "                camera_binding_needed = true;\n"
    "            }\n"
    "        }\n"
    "        recipe.items = items;\n"
    "        ViewportObjectBinding binding = {&project._project.root, scene->objects};\n"
    "        ViewportCreateDescription description = {.template = &recipe,\n"
    "            .objects = camera_binding_needed ? &binding : NULL,\n"
    "            .object_count = camera_binding_needed ? 1 : 0};\n"
    "        ViewportIdResult created = rohr_viewport_create(description);\n"
    "        if(rohr_error_check(created)) return rohr_error_result_error(created.result.error);\n"
    "        scene->viewports[i] = created.result.value;\n"
    "    }\n"
    "    return rohr_error_result_value(true);\n"
    "}\n"
    "\n"
    "static void scene_shutdown(void *context) {\n"
    "    Scene *scene = context;\n"
    "    for(size_t i = 0; i < MAX_VIEWPORTS; ++i)\n"
    "        if(scene->viewports[i]) (void)rohr_viewport_destroy(scene->viewports[i]);\n"
    "    if(rohr_entity_alive_check(scene->objects)) (void)rohr_entity_delete(scene->objects);\n"
    "    for(size_t i = ROHR_INPUT_CONTROLLER_LIMIT; i > 0; --i)\n"
    "        if(scene->controllers[i-1]) (void)rohr_input_controller_destroy(scene->controllers[i-1]);\n"
    "}\n"
    "\n"
    "int main(int argc, char **argv) {\n"
    "    EngineResult directory = rohr_directory_working_set(rohr_directory_base_get());\n"
    "    if(rohr_error_check(directory)) {\n"
    "        fprintf(stderr, \"%s\\n\", rohr_error_message_get(directory));\n"
    "        return 1;\n"
    "    }\n"
    "    Scene scene = {0};\n"
    "    Report report = rohr_scene_run(argc, argv, (SceneCallbacks){\n"
    "        .context = &scene, .initialize = scene_initialize, .shutdown = scene_shutdown\n"
    "        /* The generated scene has no developer-owned gameplay callback. */\n"
    "    });\n"
    "    if(report.diagnostic_count || report.has_fatal) rohr_report_console_write(&report);\n"
    "    return report.header.status == ROHR_REPORT_FAILED ? 1 : 0;\n"
    "}\n"
    ;
